import {wallPanelDefaults,wallPanelLayout} from './wall-panels.mjs';
export function setupWallPanelControls({getState,checkpoint,render,showDialog}){
 const section=document.createElement('section');section.className='report-controls';
 section.innerHTML='<h2>Wall panels</h2><p class="source">Vertical panels on generated building walls.</p><button id="wallPanelSetup" class="full">Wall layout &amp; cut list</button>';
 document.querySelector('#panelSettings').after(section);
 document.querySelector('#wallPanelSetup').onclick=()=>{
  const state=getState(),s={...wallPanelDefaults,...state.wallPanels};
  showDialog('Wall panels','<div class="form-grid"><label>Effective coverage (in)<input id="wallCoverage" type="number" min="1" max="120" step="0.125" value="'+s.width+'"></label><label>Maximum length (ft)<input id="wallMax" type="number" min="1" max="200" value="'+s.maxLength+'"></label><label>Total end allowance (in)<input id="wallAllowance" type="number" min="0" max="48" value="'+s.allowance+'"></label><label>Wall panel color<input id="wallColor" type="color" value="'+s.color+'"></label></div><label class="check"><input id="wallVisible" type="checkbox" '+(s.show?'checked':'')+'>Show wall panels in 3D</label><button id="applyWallPanels" class="primary full">Apply wall panels</button><p class="source">Gross rectangular walls below the eaves. Includes every section perimeter; shared interior walls, windows, doors, and gable triangles are not deducted or added. Roof panels and wall panels have separate quantities.</p><div id="wallCuts"></div>');
  const cuts=()=>{const layout=wallPanelLayout(getState()),box=document.querySelector('#wallCuts');box.replaceChildren();const note=document.createElement('p');note.textContent=`${layout.count} wall panels · ${layout.area.toFixed(1)} sq ft wall area · ${layout.orderArea.toFixed(1)} sq ft ordered blanks${layout.oversize?' · '+layout.oversize+' OVER MAXIMUM LENGTH':''}`;box.append(note);const table=document.createElement('table');const head=table.createTHead().insertRow();for(const title of ['Section / wall','Qty','Length (ft)','Check'])head.appendChild(document.createElement('th')).textContent=title;box.append(table);const body=table.createTBody();for(const row of layout.rows){const tr=body.insertRow();for(const value of [`${row.name} / wall ${row.edge}`,row.count,row.length.toFixed(3),row.length>layout.settings.maxLength?'Over maximum':'Within limit'])tr.insertCell().textContent=value}};
  document.querySelector('#applyWallPanels').onclick=()=>{const width=+document.querySelector('#wallCoverage').value,maxLength=+document.querySelector('#wallMax').value,allowance=+document.querySelector('#wallAllowance').value;if(![width,maxLength,allowance].every(Number.isFinite)||width<1||width>120||maxLength<1||maxLength>200||allowance<0||allowance>48){document.querySelector('#wallCuts').textContent='Check coverage, maximum length, and allowance limits.';return}checkpoint();getState().wallPanels={width,maxLength,allowance,color:document.querySelector('#wallColor').value,show:document.querySelector('#wallVisible').checked};render();cuts()};cuts();
 };
}
